Code.CLI:
# Example: Update RDS data source to use Secrets Manager
aws appsync update-data-source \
  --api-id <api-id> \
  --name <data-source-name> \
  --type RELATIONAL_DATABASE \
  --relational-database-config '{
    "rdsHttpEndpointConfig": {
      "awsRegion": "us-east-1",
      "dbClusterIdentifier": "<cluster-id>",
      "awsSecretStoreArn": "<secrets-manager-arn>"
    }
  }'

Code.Terraform:
```hcl
# Terraform - Use AWS Secrets Manager for database credentials
resource "aws_appsync_datasource" "rds" {
  api_id = aws_appsync_graphql_api.example.id
  name   = "rds_datasource"
  type   = "RELATIONAL_DATABASE"

  relational_database_config {
    http_endpoint_config {
      db_cluster_identifier = aws_rds_cluster.example.id
      aws_region           = "us-east-1"
      # CRITICAL: Reference Secrets Manager instead of hardcoded credentials
      aws_secret_store_arn = aws_secretsmanager_secret.db_credentials.arn
    }
  }
}
```
